      {"unit_id": "u-d95b6c4499b214b2f09e", "start_line": 5, "end_line": 12, "role": "primary", "dependency_reason": ""}
    ]
  },
  "observable_consequence": {
    "status": "established",
    "reason": "For the sixth A node, index 5 fails the parser's i < *naddrttls condition because the harness supplies 5. Its sixth TTL entry is therefore unreachable, even though the parser can return six addresses and report their count.",
